/* Atlamo chatter (extra lines, id, 2026-11-13) — the same lists in the same order as t3/ja.js (see there). */
window.AtlasNPC && AtlasNPC.more && AtlasNPC.more("id", {"sp":{"peacock":["Ekorku semuanya terbuat dari ubin mahjong! Cantik, kan?","Cuma merak jantan yang punya bulu ekor panjang yang indah!","Bintik seperti mata di bulu merak disebut oseli!","Di Shanghai, kamu mengambil ubin yang sama dua-dua!","Kamu cuma bisa ambil ubin yang tidak tertutup apa pun dan sisi kiri atau kanannya kosong!","Bunga dipasangkan dengan bunga, musim dengan musim!","Triknya, ambil dulu ubin yang menghalangi ubin lain!","Membongkar lapisan atas lebih dulu biasanya berhasil!","Merak itu keluarga burung kuau, lho! Kaget, ya?","Mahjong lahir di Tiongkok pada abad ke-19!","Aku membentangkan ekor dan menyemangatimu sekuat tenaga~!","Aku memang boneka, tapi soal pamer ekor, aku nggak kalah!"],"shogi":["Di malam yang dingin, ekor rubah bisa menjadi selimut, percayalah.","Telinga rubah amat tajam. Bahkan langkah tikus di bawah salju pun terdengar.","“Anaguma” (sarang luak) adalah nama benteng shogi yang sangat kokoh. Saya pun gemar sarang yang nyaman.","Pepatah berkata: shogi tanpa pion adalah shogi yang kalah. Hargailah bidak-bidak kecil.","Emas, perak, kuda, tombak… banyak bidak shogi bernama harta karun, sungguh.","Kabarnya, saya kerabat jauh rubah utusan kuil Inari di Jepang… begitulah desas-desusnya.","Dimulai dengan hormat, diakhiri dengan hormat. Menang atau kalah, tetap membungkuk.","Teka-teki skakmat shogi bagaikan latihan ayunan pedang. Lakukan tiap hari, niscaya makin mahir.","“Kepung raja seolah membungkusnya.” Menutup jalan larinya lebih utama daripada mengejarnya.","Bila dipromosikan, benteng dan gajah menjadi naga dan kuda. Sekutu yang amat tangguh.","Bulu saya hari ini tampak sangat berkilau, bukan?","Lengah adalah musuh terbesar. Justru saat kemenangan terlihat, kuatkan hatimu."],"knight":["Kuda bisa tidur sambil berdiri. Rekan seorang ksatria memang pekerja keras!","Mata kuda ada di sisi kepala, jadi ia bisa melihat hampir ke segala arah.","Kata orang, kuda di tepi papan kurang berguna. Mari, kita melaju ke tengah!","Setiap kali bergerak, aku berpindah antara petak terang dan petak gelap.","Ada teka-teki terkenal bernama “tur kuda”: mengunjungi setiap petak papan tepat satu kali.","Di awal partai catur, hanya pion dan aku yang bisa bergerak.","Garpu! Menyerang dua bidak sekaligus adalah jurus andalan ksatria.","Dalam notasi catur, aku ditulis “N” agar tidak tertukar dengan raja (King).","Dalam bahasa Jerman, aku disebut “Springer”, artinya si pelompat.","Konon baju zirah ksatria abad pertengahan beratnya sekitar 20 kg. Zirahku jauh lebih ringan!","Saat ragu, aku melaju ke tempat yang pertahanannya paling tipis.","Tuanku, hari ini pun akan kupersembahkan kemenangan untukmu!"],"disc":["Kura-kura itu… bisa hidup puluhan tahun… kura-kura raksasa malah lebih dari 100 tahun… zzz.","Tempurungku… menyatu dengan tulang punggung… jadi tidak bisa dilepas…","Papan reversi itu 8×8… 64 petak… menghitungnya bikin ngantuk…","Di awal permainan… katanya lebih baik jangan membalik terlalu banyak keping… aneh, ya…","Petak X… yang diagonal di sebelah sudut… di situ berbahaya, lho…","Lomba kancil… eh, kelinci dan kura-kura… aku percaya yang pelan pun bisa menang…","Kadang langkah terakhir… membalik semuanya… deg-degan…","Berjemur di bawah matahari… hangat… paling enak…","Kura-kura darat… katanya hampir tidak bisa berenang… aku yang mana, ya…","Mengambil tepi papan pun… jangan buru-buru… pikirkan pelan-pelan…","Kalau dibalik… tinggal bangun lagi saja… hoaam.","Datanglah pelan-pelan saja… aku jago menunggu…"],"tile":["Sudoku punya 81 sel. Saya mengawasi 27 kelompok sekaligus: baris, kolom, dan blok.","Sudoku yang baik harus punya tepat satu jawaban.","Telah dibuktikan bahwa sudoku dengan jawaban tunggal butuh setidaknya 17 angka awal.","Nama “Sudoku” diberikan oleh perusahaan teka-teki Jepang, Nikoli.","Teka-teki asal sudoku dulu disebut “Number Place” di Amerika Serikat.","Cara mengisi kisi 9×9 dengan benar ada sekitar 6,67×10²¹ cara.","Mencatat angka kandidat kecil-kecil juga strategi yang hebat.","Kalau buntu, lihat dulu baris atau kolom yang angkanya sudah banyak terisi.","Sudoku tidak butuh hitungan. Angka hanya dipakai sebagai simbol.","Bip bip bip… sirkuit hitung saya hari ini dalam kondisi prima.","Robot pun sesekali beristirahat dan mengencangkan sekrupnya.","Rasa “klik” saat teka-teki terpecahkan adalah kebahagiaan yang tak bisa diungkapkan data."],"stone":["…Penguin itu burung, tapi terbangnya di laut, bukan di langit.","Konon penguin kaisar bisa menyelam lebih dari 500 meter.","…Ada pepatah: hafalkan joseki, lalu lupakan.","Warna hitam-putih tubuhku membuatku sulit terlihat di dalam laut.","Di hari dingin, kami berkerumun rapat. …Batu go juga lebih kuat kalau tersambung.","…Di Jepang, ungkapan “memberi satu batu” berarti menghormati seseorang. Asalnya dari membiarkan pemain kuat yang diberi batu duluan.","“Atari”… artinya batu tinggal punya satu jalan keluar.","…Penguin juga punya lutut. Hanya tersembunyi di balik bulu.","Di go, yang wilayahnya lebih luas di akhir yang menang. …Aku memperluasnya diam-diam.","…Mengepung wilayah lebih penting daripada menangkap batu.","…Meluncur di atas es dengan perut itu lumayan seru.","…Langkah berikutnya, pikirkan saja pelan-pelan."],"dot":["Ciap! Anak ayam berciap dari dalam telur sambil mematuk cangkangnya!","Telur ayam biasanya menetas dalam sekitar 21 hari~!","Kotak yang sudah bergaris tiga itu bahaya! Nanti malah jadi milik lawan!","Kalau titiknya 4×4, kotaknya 3×3, jadi 9! Menghitung itu seru!","Anak ayam bisa langsung berjalan begitu menetas, lho! Hebat, kan!","Untuk menggambar garis, cukup satu pensil! Ciap!","Mengambil rantai panjang terakhir sampai habis itu rasanya puas banget~!","Aku suuuka permainan yang bisa dimainkan di pojok buku tulis!","Kalau bisa bikin kotak, ambil! …Tapi kadang menahan diri juga penting, katanya!","Ciap ciap… boleh kok pegang buluku yang lembut!","Leluhur ayam itu ayam hutan merah dari hutan Asia Tenggara, lho!","Selanjutnya garisnya di mana, ya~?"],"plop":["Telinga kelinci yang panjang itu seperti radiator untuk membuang panas tubuh!","Kalau senang aku melompat sambil memutar! Namanya “binky”!","Kalau sudah tiga bersusun tegak, satu lagi di atasnya menang! Jangan sampai terlewat ya!","Mata kelinci ada di samping kepala, jadi bisa melihat sampai ke belakang~!","Kuncinya, temukan dulu petak yang gawat kalau diisi lawan!","Keping bertumpuk dari bawah, jadi pikirkan mulai dari baris bawah!","Gigi kelinci tumbuh terus seumur hidup! Makanya aku menggigit-gigit terus~!","Pemain hebat memperhatikan baris ganjil dan genap, lho! Susah~!","Wortel enak, tapi sebenarnya aku paling suka rumput!","Plop, plop… mendengar suaranya saja aku sudah semangat!","Di Jepang, ada cerita lama bahwa kelinci tinggal di bulan!","Empat diagonal sering terlewat, jadi hati-hati ya!"],"gem":["Beberapa sepupu kumbangku berkilau seperti logam, lho.","Di Mesir kuno, kumbang tinja adalah lambang dewa matahari.","Biji biasanya ditabur berlawanan arah jarum jam, tapi di beberapa daerah arahnya terbalik.","Kalau biji terakhir masuk ke lumbungmu sendiri, main sekali lagi! Untung, kan?","Biji terakhir jatuh di lubang kosong… biji di seberangnya diborong semua! Itulah nikmatnya berdagang.","Mancala itu permainan menghitung. Tabur sambil menghitung dengan jari.","Kumbang badak itu kuat sekali, bisa menarik beban jauh lebih berat dari tubuhnya.","Hafalkan jumlah biji, maka langkah lawan berikutnya bisa terbaca.","Jangan menimbun berlebihan. Biji yang tersisa di akhir dikemanakan, tergantung aturannya.","Pendapatan hari ini… eh, kita sedang bicara soal biji. Silakan, silakan!","Sayapku yang berkilau ini kugosok setiap pagi.","Terima kasih banyak! Pelanggan berikutnya, silakan mampir!"],"dice":["Katanya hidung anjing puluhan ribu kali lebih tajam dari hidung manusia!","Sisi dadu yang berhadapan kalau dijumlah pasti 7! Tahu, kan?","Lempar dua dadu, jumlah yang paling sering keluar itu 7! Ada 6 cara, lho!","Di backgammon, kalau dapat dobel, kamu bisa bergerak 4 kali!","Mengibaskan ekor itu tanda untuk menunjukkan perasaanku!","Bidak sendirian, “blot”, jadi incaran! Bertahan juga harus membara!","Enam titik berjajar yang diblokir, “prime”, adalah tembok yang tak bisa dilewati!","Di Romawi kuno pun dadu sangat populer!","Rute jalan-jalanku sama setiap hari! Tapi tetap seru setiap hari!","Lagi sial? Jangan cemberut! Lemparan berikutnya bisa membalikkan keadaan!","Di Jepang, titik satu pada dadu biasanya berwarna merah!","Oke, ayo lempar dengan semangat!"],"owl":["Burung hantu bisa memutar kepala hampir 270 derajat. Hu hu.","Tepi bulu kami bergerigi, jadi kami bisa terbang hampir tanpa suara.","Membuka dan menutup mill berkali-kali untuk terus mengambil… hehehe, licik, kan?","Ada aturan yang membolehkan bidak terbang ke mana saja kalau tinggal tiga.","Mata burung hantu tidak bisa bergerak. Makanya kepala yang kuputar.","Aku dijuluki “si bijak hutan”, tapi kadang salah injak dahan juga.","Terlalu serakah saat menaruh bidak, nanti tak bisa bergerak… itu juga bagian dari siasat.","24 titik, masing-masing 9 bidak… papan morris adalah persegi di dalam persegi.","Telinga kiri dan kanan burung hantu beda tinggi, jadi bisa melacak asal suara dengan tepat.","Dalam bahasa Jepang, burung hantu (fukurō) bisa dibaca “tanpa kesusahan”. Nama pembawa untung, bukan?","Hehe, kalau teman begadang, aku selalu siap.","Nah, jebakannya sudah kupasang. Coba tebak di mana?"],"crab":["Kepiting jago jalan menyamping, tapi ada juga kepiting yang bisa jalan lurus!","Capit yang putus akan tumbuh lagi setelah berganti kulit!","Di dam, kalau bisa menangkap, wajib menangkap! Itu hukum laut!","Bidak di tepi papan sulit ditangkap. Seperti kapal di pelabuhan!","Bidak yang jadi raja kekuatannya seratus orang! Jangan lewatkan harta karun itu!","Lompat, lompat, tangkap beruntun! Inilah tangkapan besar bajak laut!","Papan aturan internasional 10×10! Lautan itu luas!","Kalau naik ke darat, kepiting mengeluarkan gelembung busa!","Saat badai, kapal maupun bidak sama-sama memperkuat pertahanan!","Membaca papan lebih penting daripada peta harta karun!","Cangkangku keras, tapi hatiku lembut!","Baiklah, kembangkan layar! Kita berlayar!"],"rook":["Belalai gajah itu… punya puluhan ribu otot, lho…","Gajah liar itu… cuma tidur sebentar… kalau aku sih tidur lama…","Benteng itu… di akhir permainan… jadi kuat sekali…","Benteng di baris ketujuh… katanya kuat… zzz.","Gajah itu… mengepak-ngepakkan telinganya yang besar… untuk mendinginkan badan…","Di catur India zaman dulu… yang berdiri di tempatku itu kereta perang…","Rokade itu… cuma sekali dalam satu partai… pakai baik-baik ya…","Ada penelitian… katanya gajah saling memanggil dengan suara seperti nama…","Dua benteng… dijajarkan di satu lajur… kekuatannya luar biasa…","Maju lurus itu enak… karena tidak bakal tersesat…","Tidur siang di atas menara benteng… paling menenangkan…","Pelan-pelan saja… aku tunggu di sini…"],"bishop":["Bulu alpaka itu ringan dan hangat.","Alpaka buang kotoran di tempat yang sudah ditentukan bersama. Kami suka kebersihan.","Gajah catur tidak akan pernah bisa meninggalkan warna petak awalnya.","Dua gajah bersama disebut “pasangan gajah”. Sungguh menenangkan hati.","Kami alpaka berasal dari pegunungan tinggi Andes di Amerika Selatan.","Diagonal panjang adalah panggung kehormatan bagi gajah.","Bidak ini dulu memang gajah. Di Barat namanya berubah menjadi uskup (bishop).","Celah di kepalaku meniru bentuk topi uskup.","Katanya alpaka suka meludah… tetapi saya tidak akan melakukannya.","Dengan hati yang tenang, jalan diagonal akan tampak dengan sendirinya.","Bulu tebal kami dicukur setahun sekali.","Semoga langkah yang baik datang kepadamu."],"pawn":["Mbeek! Bulu domba terus tumbuh kalau tidak dicukur!","Ada cara menangkap khusus yang hanya bisa dilakukan pion, namanya “en passant”!","Pion maju lurus, tapi menangkapnya diagonal! Aneh, ya~!","Pion tidak bisa mundur. Jadi setiap langkah harus dipikirkan baik-baik!","Domba bisa mengingat wajah puluhan temannya, lho!","Ada pemain hebat zaman dulu yang bilang “pion adalah jiwa catur”!","Pion yang tersambung diagonal itu kuat sekali!","Biasanya pion jadi ratu, tapi kadang memilih kuda, lho!","Di awal catur, pion ada 8 di tiap pihak! Keluarga paling besar!","Dengan bulu yang empuk, aku bisa tidur siang kapan saja! Mbeek~","Langkah kecil pun, kalau dikumpulkan, bisa sampai ke tujuan!","Aku akan berusaha sampai ke ujung papan! Mbeek!"],"ryuou":["Turnamen Ryūō adalah salah satu gelar shogi paling bergengsi, ketahuilah.","Dalam bahasa Jepang, “naga” bisa ditulis dengan dua huruf kanji. Keduanya adalah aku.","Benteng yang dipromosikan menjadi Raja Naga, gajah menjadi Kuda Naga. Kami bersaudara naga!","Menurut legenda, naga memanggil awan dan menurunkan hujan.","Dari dua belas hewan shio, hanya naga makhluk khayalan. Itulah aku.","Satu langkahku mengubah suasana seluruh papan. Itulah bidak besar!","Bila naga dan kuda sudah ada di papan, kekalahan jarang terjadi.","Huahaha, skak sekaligus serang benteng… eh, jangan sampai aku yang ditangkap!","Permataku makin bersinar setiap kali aku menang.","Di Tiongkok, naga sejak lama dihormati sebagai lambang kaisar.","Naiklah ke punggungku, akan kubawa kau terbang di atas awan.","Baiklah, hari ini pun akan kupinjamkan kekuatanku!"],"keima":["Gigi tikus juga tumbuh seumur hidup. Makanya aku selalu menggigit-gigit!","Shio pertama adalah tikus! Katanya ia melompat turun dari punggung kerbau di garis akhir!","Kuda shogi yang dipromosikan bergerak sama seperti jenderal emas!","Kuda shogi tidak boleh dijatuhkan di dua baris terakhir, karena tak bisa bergerak lagi!","Beda dengan kuda catur, aku hanya bisa melompat ke depan. Sekali tembak!","Kata pepatah Jepang, kuda yang melompat terlalu tinggi jadi santapan pion!","Aku jago menjaga keseimbangan dengan ekor! Cit!","Garpu kuda pada dua bidak di Jepang disebut “kuda cawat”! Keren, kan?","Asal ada lubang kecil, aku bisa menyelinap ke mana saja!","Keju boleh juga, tapi sebenarnya aku lebih suka biji-bijian!","Aku bisa melompati bidak lain. Di shogi, itu keahlian khususku!","Cit cit, selanjutnya aku lompat ke mana, ya?"],"flippanda":["Panda itu… makan bambu… lebih dari sepuluh jam sehari…","Tangan panda… punya tulang seperti jari keenam… untuk memegang bambu…","Kenapa panda hitam-putih… katanya masih diteliti…","Bayi panda… waktu lahir… beratnya cuma sekitar 100 gram…","Di reversi… menyisakan lebih banyak tempat untuk melangkah… itu menguntungkan…","Yang melangkah terakhir untung… “teori genap”… susah, ya…","Putih atau hitam… jadi yang mana pun… aku tetap panda… tidak apa-apa…","Memanjat pohon juga… sebenarnya jago… walau kadang jatuh…","Berguling di tempat tidur… itulah cara panda membalik…","Di akhir permainan… kalau dihitung… kelihatan siapa yang menang…","Panda itu… sebangsa beruang, lho…","Hoaam… ayo… santai-santai bareng…"],"goke":["Tanuki itu kalau kaget langsung membeku, Bos. Katanya itu asal ungkapan Jepang “tidur ala tanuki” alias pura-pura tidur.","Mangkuk go ada juga yang mewah, dari kayu kastanye atau murbei, lho.","Batu putih kelas atas terbuat dari cangkang kerang!","Untuk batu hitam, batu “Nachi-guro” dari Jepang yang terkenal!","Satu set batu go standarnya 181 hitam dan 180 putih, Bos.","Tanuki itu sebangsa anjing, lho. Sebenarnya kami juga bisa memanjat pohon!","Tutup mangkuk go dipakai untuk menaruh batu tangkapan, Bos.","Memperkirakan wilayah di go… menghitung itu dasar berdagang!","Patung tanuki keramik Shigaraki di Jepang itu? Itu leluhurku dalam pakaian terbaiknya!","Siap, terima kasih! Hari ini jangan salah taruh batu, ya.","Dagang maupun go, kalau terlalu serakah pasti gagal, Bos.","Perutku hari ini penuh batu go, lho!"],"renju":["Tupai mengubur biji ek di tanah, lalu menggalinya di musim dingin!","Biji ek yang lupa dikubur di mana bisa tumbuh jadi pohon baru!","Bikin empat dan tiga sekaligus, “empat-tiga”! Itu hampir pasti menang!","Di renju, Hitam dilarang membuat tiga-tiga, empat-empat, dan deretan lebih dari lima!","Papan renju 15×15! Lebih kecil dari papan go~!","Putih tidak punya langkah terlarang, jadi enam berderet pun tetap menang!","Ekorku yang lebat sangat berguna untuk menjaga keseimbangan!","Tutup kedua ujung “tiga” milik lawan secepatnya, ya!","Dari atas pohon, deretan di papan kelihatan jelas~!","Setiap batu yang dijajarkan bikin makin deg-degan!","Aku menjajarkan lima biji ek… eh, satu sudah kumakan!","Hehe, nanti kita jajarkan lima bersama, yuk!"],"camel":["Punuk unta tidak berisi air, melainkan lemak, Nak.","Unta bisa minum banyak sekali dalam sekali minum. Terkadang lebih dari 100 liter.","Bulu mata yang panjang ini gunanya melindungi mata dari pasir.","Dahulu jam pasir juga dipakai untuk mengukur waktu di atas kapal.","Aku menutup lubang hidung untuk bertahan dari badai pasir.","Konon di turnamen catur zaman dulu, waktu pemain pernah diukur dengan jam pasir.","Unta berpunuk satu atau berpunuk dua… aku yang mana, ya? Ho ho.","Dalam perjalanan yang terburu-buru pun, secangkir teh untuk beristirahat memberi kekuatan.","Saat detik-detik terakhir, tarik napas dalam sekali. Pasir jatuh dengan tenang.","Malam di gurun itu dingin. Siang dan malam sangat berbeda.","Waktu tak bisa kembali. Karena itu, hargailah langkahmu saat ini.","Ho ho, mari kita melangkah perlahan-lahan."],"ringsnake":["…Ular tidak punya kelopak mata. Jadi mata kami selalu terbuka.","Aku menjulurkan lidah untuk mengumpulkan bau.","Kulit hasil ganti kulitku tertinggal dalam keadaan terbalik. …Aneh, kan.","Untuk teka-teki cincin kawat, pikirkan cincinnya “digeser”, bukan “dimasukkan”.","Kadang memasang kembali teka-teki cincin yang sudah terlepas justru lebih sulit.","Kalau dingin, aku tak bisa bergerak. …Berjemur itu penting.","…Ouroboros, ular yang menggigit ekornya sendiri, adalah lambang ketakterhinggaan.","Ular tak punya lubang telinga, tapi bisa merasakan suara dari getaran tanah.","Kalau kusut, lepaskan semuanya dan mulai dari awal. …Itu juga sebuah jawaban.","…Ular bisa menelan mangsa besar bulat-bulat. Rahangnya tersambung dengan lentur.","…Waktu untuk berpikir dengan tenang, aku tidak benci.","…Nah, mari pecahkan teka-teki berikutnya."],"joker":["Kucing tidur lebih dari separuh hari, meong.","Kumisku itu sensor untuk mengukur apakah aku muat lewat celah, meong.","Satu dek kartu isinya 52 lembar, 53 kalau ditambah joker, meong.","52 lembar itu sama dengan jumlah minggu dalam setahun, meong!","Joker bergabung ke dek kartu di Amerika abad ke-19, meong.","Kucing yang jatuh dari tempat tinggi bisa berputar dan mendarat dengan kaki, meong.","Sebagai kartu liar, joker mengamuk di poker, meong.","Tahukah kamu, King hati satu-satunya King yang tidak berkumis, meong?","Mendengkur itu bukan cuma tanda senang, lho, meong.","Kartu trufku selalu aku sendiri, meong.","Bantalan kaki kucing adalah salah satu dari sedikit tempat kucing berkeringat, meong.","Meong-haha, keisengan apa lagi yang akan kulakukan, meong?"],"hedgehog":["Landak mini punya sekitar 5.000 duri, lho!","Kalau aku meringkuk, aku berubah jadi bola berduri!","Ada teori bahwa simbol hati di kartu berasal dari lambang cawan suci!","Kalau malam aku jadi bersemangat! Aku hewan nokturnal~!","Landak mini dan landak besar itu bukan satu keluarga, lho!","Kartu bergambar ada 12: J, Q, dan K di empat jenis kartu!","Landak mini membawa apel di punggung? Sebenarnya itu cuma cerita karangan!","As hati itu rasanya istimewa, ya!","Kalau deg-degan, duriku langsung berdiri tegak!","Endus endus… hidung yang bergerak-gerak itu tanda aku senang!","Solitaire itu permainan kartu yang bisa dimainkan sendirian, lho!","Pelukan agak susah, tapi tos bisa kok!"],"momonga":["…Bajing terbang meluncur dengan selaput di antara kaki depan dan belakangnya.","Dari pohon ke pohon, kami bisa meluncur sampai puluhan meter.","Dulu di Inggris, tanda pajak dicetak di kartu As sekop.","Bajing terbang raksasa dan momonga… momonga jauh lebih kecil.","Mata besar ini supaya bisa melihat jelas di hutan malam.","…Di bridge, sekop adalah jenis kartu terkuat.","Sebelum melompat, aku memperhatikan tempat mendarat. …Bertanding juga sama.","Ekorku adalah kemudi. …Berkat ekor inilah aku bisa terbang lurus.","…Aku suka saat tenang sebelum fajar.","Di blackjack, As sekop dan Jack itu kombinasi keren. …Cuma bilang saja.","…Dari tempat tinggi, seluruh papan terlihat jelas.","…Ayo."],"koala":["Koala tidur… sekitar 20 jam sehari…","Daun kayu putih itu beracun… tapi koala tidak apa-apa…","Sidik jari koala… katanya mirip sekali dengan manusia…","Bayi koala… tumbuh di kantong perut ibunya…","Semanggi berdaun empat… katanya cuma ada satu dari sepuluh ribu…","Koala… jarang minum air… airnya didapat dari daun…","Di permainan kartu… keriting sering jadi jenis kartu paling lemah…","Baccarat itu… yang paling dekat ke 9 menang… kalau cuma menunggu kartu… sambil tidur pun bisa… zzz.","Kalau memeluk pohon… rasanya tenang…","Berpikir pelan-pelan juga… tidak apa-apa… zzz…","Hutan kayu putih di Australia… itulah kampung halamanku…","Selamat tidur… eh, bukan… ayo main…"],"otter":["Waktu tidur, berang-berang laut membungkus tubuhnya dengan rumput laut supaya tidak hanyut!","Kadang mereka bergandengan tangan dan tidur sambil mengapung~!","Di bawah ketiakku ada kulit longgar seperti kantong untuk menyimpan batu favoritku!","Bulu berang-berang laut paling lebat di antara semua hewan!","Ubin mahjong totalnya 136! Ada juga aturan yang menambahkan ubin bunga~!","Ubin satu bambu sering bergambar burung!","Empat set dan satu pasang membentuk tangan menang!","Ubin naga putih kelihatan polos, tapi itu ubin kehormatan sungguhan!","Memecah kerang di atas perut dengan batu itu keahlianku~!","Mengapung-apung… selanjutnya buang ubin yang mana, ya~?","Ubin mahjong Timur, Selatan, Barat, Utara itu melambangkan angin!","Ayo main bersama dengan santai dan gembira~!"],"deer":["Tanduk rusa berganti setiap tahun, lho.","Hanya rusa jantan yang bertanduk… tetapi rusa kutub betina juga punya, lho.","Hanafuda punya 12 bulan, masing-masing 4 kartu, jadi 48 kartu. Kartu-kartu musim, begitulah.","Bulan Oktober di hanafuda adalah daun maple. Yang tergambar di sana adalah saya.","“Babi hutan-rusa-kupu-kupu”: babi hutan di semak hagi, rusa di daun maple, kupu-kupu di peoni. Kombinasi yang anggun, bukan?","Rusa di Nara, Jepang, kadang membalas membungkuk bila Anda membungkuk kepadanya.","“Minum di bawah bunga sakura”, “minum di bawah bulan”… sungguh kombinasi yang berselera tinggi.","Bulan November di hanafuda adalah pohon willow. Kartu hujannya bergambar kaligrafer Ono no Michikaze.","Menunggu pergantian musim dengan tenang juga merupakan sebuah langkah.","Musim daun merah adalah saat saya paling bersinar.","Kerupuk rusa di Nara adalah kerupuk khusus untuk rusa, lho.","Baiklah, mari kita bermain dengan anggun."],"seal":["Anjing laut tidak punya daun telinga! Singa laut punya!","Di darat, aku maju dengan menyeret perut~!","Kartu menko di Jepang punya banyak nama berbeda tergantung daerahnya, lho!","Anjing laut merasakan arus air dengan kumisnya untuk mencari ikan!","Katanya menko zaman dulu ada yang terbuat dari tanah liat yang dibakar!","Bayi anjing laut tutul itu putih bersih, lho~!","Sudut saat membanting itu penting! Dari samping miring, hiyaat!","Ada anjing laut yang bisa menyelam lebih dari satu jam, lho!","Gambar di menko selalu memuat pahlawan populer di zamannya!","Guling-guling, hangat-hangat… tapi kalau bertanding, aku serius!","Tidur siang di atas es itu paling enak~!","Plok plok dengan sirip! Aku menyemangatimu!"],"duck":["Kaki bebek punya trik khusus supaya tidak membeku di air dingin!","Anak bebek mengira benda bergerak pertama yang dilihatnya adalah induknya! Itu namanya “imprinting”!","Satu set domino standar isinya 28 kartu!","Rekor dunia domino jatuh itu menjajarkan jutaan domino!","Rahasia bulu antiair adalah minyak dari pangkal ekor!","Titik domino dari 0 sampai 6! Seperti dadu ditambah nol!","Terbang membentuk huruf V supaya bisa memanfaatkan angin dari teman di depan!","Saat menyusun, sisakan celah! Itu teknik para ahli!","Di atas air anggun, di bawah air mengayuh sekuat tenaga! Itulah gaya hidupku!","Kwek! Hari ini pun habis-habisan!","Satu jatuh, semua jatuh! Dalam bertanding pun momentum itu penting!","Oke, ayo susun! Fokus!"],"hamster":["Kantong pipi hamster bisa melar sampai ke bahu, cit!","Hamster jadi bersemangat di malam hari. Aku juga tipe malam, cit.","Di roda putar, kami bisa berlari berkilo-kilometer dalam semalam, cit!","Gerigi di tepi koin itu peninggalan zaman dulu untuk mencegah logamnya dikikis, cit.","Menyelesaikan misi harian adalah jalan pintas terbaik, cit.","Gigi hamster juga tumbuh seumur hidup. Menggigit itu pekerjaan penting, cit.","Koin 5 yen dan 50 yen Jepang punya lubang di tengahnya, cit.","Hamster emas suka hidup sendirian, cit.","Menabung sedikit demi sedikit setiap hari. Itu pesan keluarga hamster, cit.","Sebelum memutar gacha, tarik napas dalam dulu, cit!","Biji bunga matahari itu hidangan istimewa, tapi jangan kebanyakan, cit.","Isi pipiku… rahasia, cit!"],"piglet":["Babi itu pintar sekali, sampai bisa memakai cermin untuk mencari benda!","Babi hampir tidak berkeringat, jadi kami berkubang lumpur untuk mendinginkan badan~!","“Kasur rusak” dibaca dari belakang tetap “kasur rusak”! Itu palindrom! Di Jepang contohnya “shinbunshi” (koran).","Dalam bahasa Jepang hampir tak ada kata berawalan “n”… tapi ada! Ibu kota Chad, “N'Djamena”!","Hidung babi bisa menemukan jamur truffle di dalam tanah, lho!","“Katak” juga palindrom~! Di Jepang ada “takeyabu yaketa” (rumpun bambu terbakar)!","Anagram itu mengacak huruf! Dalam bahasa Jepang, “tokei” (jam) diacak jadi “keito” (benang wol)!","“Mutiara untuk babi”? Aku lebih suka kata-kata daripada mutiara!","Di shiritori (sambung kata Jepang), triknya membuat lawan harus mencari kata berawalan “ru”!","Oink oink! Kata pilihan hari ini adalah “sahabat karib”!","Kata yang bunyinya sama tapi artinya beda, banyak sekali di bahasa Jepang, ya!","Semakin sering bermain kata, semakin suka pada kata-kata!"],"beaver":["Bendungan berang-berang yang panjang bisa lebih dari 800 meter!","Gigi depan berang-berang berwarna oranye karena banyak zat besinya!","Balok yang berat di bawah! Itu aturan wajib!","Kami menampar air dengan ekor untuk memperingatkan teman-teman akan bahaya!","Permainan menarik balok itu soal konsentrasi ujung jari!","Kadang kami bisa merobohkan satu pohon dalam semalam!","Pintu masuk sarang berang-berang ada di dalam air! Musuh tak bisa masuk!","Untuk menyusun tinggi, susun lurus dulu! Goyangan tak bisa diperbaiki dengan nekat!","Berang-berang tinggal di Amerika Utara dan Eurasia!","Oke, hari ini aku mau menggigit satu pohon… eh, maksudku menang satu partai!","Aku ingin memamerkan bendunganku! Itu mahakaryaku!","Fondasi itu penting! Bangun permainanmu dari dasar!"],"snail":["Siput punya… ribuan gigi kecil… seperti kikir…","Mataku… ada di ujung tentakel yang panjang…","Kami keluar saat hujan… karena tidak tahan kering…","Menara Hanoi itu… teka-teki memindahkan cakram satu per satu… pelan-pelan…","Kalau cakramnya 3… paling sedikit 7 langkah… kalau 64… tak terbayangkan…","Cangkang ini… sudah kupunya… sejak lahir…","Siput itu… katanya punya sifat jantan dan betina sekaligus…","Lendir ini… lengket yang penting… untuk melindungi tubuh…","Pelan pun… asal tidak berhenti… tetap maju…","Pemandangan dari puncak menara… pasti… indah sekali…","Musim bunga hortensia… paling kusuka…","Ayo… pelan-pelan… kita panjat bersama…"],"hippo":["Keringat kuda nil kelihatan kemerahan… katanya berfungsi seperti tabir surya…","Kuda nil itu… lebih jago berjalan di dasar air… daripada berenang…","Kubus Rubik… lahir di Hungaria… tahun 1974…","Kombinasi kubus… lebih dari 43 triliun juta… hoaam…","Dari keadaan apa pun… katanya bisa diselesaikan… dalam 20 langkah atau kurang…","Mulutku yang besar… bisa terbuka… sekitar 150 derajat…","Daripada satu sisi demi satu sisi… lebih baik… satu lapis demi satu lapis…","Di dalam air… aku bisa menahan napas… beberapa menit…","Bayi kuda nil… kadang lahir di dalam air…","Berpikir santai di dalam air… ide bagus… mengapung keluar…","Kuda nil itu… katanya kerabat jauh paus…","Putar, putar… eh… balik lagi ke awal…"],"mole":["Tikus tanah makan sekitar setengah berat tubuhnya setiap hari.","Kaki depan tikus tanah menghadap ke luar, seperti sekop.","Dengan “metode tangan kanan” di labirin, kamu pasti sampai di pintu keluar asalkan dindingnya tersambung.","Mata tikus tanah kecil, tetapi indra di hidungnya sangat tajam.","Legenda labirin yang terkenal adalah labirin Minotaurus dalam mitologi Yunani.","Bentuk berjalur tunggal yang berliku menuju pusat kadang secara khusus disebut “labirin klasik”.","Suhu di dalam terowongan stabil dan nyaman.","Ada juga cara memecahkan dengan menelusuri balik dari jalan buntu.","Tikus tanah katanya tidak suka cahaya, tetapi kami bisa merasakan terang.","Justru jalan tanpa peta yang paling layak diteliti.","Dasar meloloskan diri: pertama, pastikan dulu letak pintu keluar.","Nah, hari ini kita gali jalan yang mana?"],"crane":["Burung jenjang sering hidup bersama pasangan yang sama seumur hidup.","Bagian merah di kepala jenjang mahkota merah itu kulit, bukan bulu.","“Jenjang hidup seribu tahun, kura-kura sepuluh ribu tahun.” Di Jepang, keduanya lambang panjang umur.","Burung jenjang kertas dilipat dari selembar kertas persegi.","Seribu burung kertas dirangkai dengan benang sambil menitipkan harapan.","Tarian jenjang saat mencari pasangan sungguh anggun.","“Origami” kini juga dipakai dalam bahasa Inggris. Sudah menjadi kata dunia.","Semakin pelan melipat, semakin rapi sudut-sudutnya.","Jenjang mahkota merah hidup di rawa-rawa Hokkaido, Jepang.","Ada rekor dunia untuk lamanya pesawat kertas melayang di udara.","Dalam selembar kertas pun, tersimpan bentuk yang tak terhingga.","Baiklah, mari kita lakukan dengan teliti."],"goat":["Kambing itu ahli berpijak, bisa memanjat tebing dengan lincah.","Pupil kambing memanjang ke samping, Nak. Supaya bisa memandang luas.","Permainan tali dimainkan di seluruh dunia. Sebuah budaya tali.","Masyarakat Arktik pun mewariskan teknik permainan tali sejak dahulu.","“Sapu”, “Menara Tokyo”… nama-nama bentuk permainan tali di Jepang pun menyenangkan.","Katanya kambing makan kertas, padahal sebenarnya itu tidak baik untuk tubuh kami.","Kalau talinya kusut, periksa arah mengurainya satu per satu.","Dari susu kambing bisa dibuat keju yang lezat.","Waktu muda, aku sering tidur siang di puncak gunung.","Jenggot panjang ini tanda kebijaksanaan yang bertambah… begitulah anggapanku.","Main tali sendirian atau berdua, yang terpenting hati yang tenang.","Ho ho, mari kita pintal perlahan-lahan."],"dragonfly":["Mata capung terdiri dari puluhan ribu mata kecil!","Capung bisa diam melayang di udara, bahkan terbang mundur!","Katanya baling-baling bambu sudah dimainkan di Jepang sejak zaman Edo!","Capung hanya terbang maju, jadi di Jepang disebut “serangga kemenangan”! Para samurai menyukainya!","Rahasia baling-baling bambu menangkap angin ada di sayapnya yang terpilin!","Anak capung, nimfa, hidup di dalam air!","Yang hebat, keempat sayapku bisa digerakkan sendiri-sendiri!","Angin hari ini dari belakang! Ayo, bisa!","Putar, putar! Yang terbang paling tinggi menang!","Capung merah di langit musim gugur itu keren, kan!","Awal yang cepat itu kuncinya! Langsung tancap gas!","Oke, ayo terbang kencang!"],"butterfly":["Kupu-kupu merasakan rasa dengan kakinya, lho.","Kaleidoskop diciptakan sekitar tahun 1816 oleh Sir Brewster dari Skotlandia.","Di dalam kaleidoskop, cermin-cermin memantulkan pola berulang kali.","Warna sayap kupu-kupu berasal dari sisik kecil yang memantulkan cahaya.","Kupu-kupu raja menempuh perjalanan ribuan kilometer.","Di dalam kepompong, kupu-kupu menyusun ulang tubuhnya sepenuhnya.","Dalam bahasa Jepang, kaleidoskop ditulis “cermin sepuluh ribu bunga”… indah sekali, bukan?","Tak ada dua pola yang sama… pertandingan pun begitu juga.","Nektar bunga kami isap dengan mulut seperti sedotan.","Putar sedikit, pemandangan pun baru. Mengganti suasana hati juga penting.","Padang rumput di musim semi adalah aula dansa kami.","Baiklah, mari kita bermain dengan memesona."],"monkey":["Uki uki! Monyet Jepang adalah monyet yang tinggal paling utara di dunia!","Ada monyet yang berendam di pemandian air panas, lho! Yang terkenal di Jigokudani, Nagano!","Katanya yoyo sudah ada sejak Yunani kuno!","Ada teori bahwa kata “yoyo” berasal dari bahasa Filipina!","Tahu trik “mengajak anjing jalan-jalan”? Yoyonya digelindingkan di lantai!","Monyet berteman dengan saling merapikan bulu. Uki.","Ada astronaut yang main yoyo di dalam pesawat luar angkasa, lho!","Monyet yang bisa memegang dahan dengan ekor itu monyet dari Amerika Tengah dan Selatan!","Tipuan dulu, baru langkah sungguhan! Inilah gaya Uki uki!","Hati-hati kulit pisang, ya! Ukyakya!","Kalau talinya kusut… anggap saja kamu tidak lihat, ya!","Nah, mau main apa? Uki uki!"],"teddy":["Nama boneka teddy berasal dari “Teddy”, nama panggilan Presiden Amerika Roosevelt!","Perusahaan Steiff dari Jerman juga sudah lama membuat boneka beruang!","Beruang sungguhan katanya punya penciuman yang luar biasa tajam!","Saat hibernasi, beruang tidak apa-apa walau tidak makan apa pun!","Di dunia ada juga museum boneka teddy, lho!","Kalau dipeluk erat, jadi semangat, kan?","Mata kancingku agak miring, itu daya tarikku!","Menang atau kalah, akhirnya tetap berteman!","Terima kasih sudah main bersamaku!","Mau coba pegang telingaku yang lembut?","Hari ini ada kejadian seru apa?","Ayo kita cari permainan favoritmu bersama!"],"bee":["Lebah madu memberi tahu letak bunga kepada teman-temannya dengan “tarian angka 8”!","Madu yang dikumpulkan seekor lebah seumur hidupnya cuma sedikit sekali! Ini kekuatan bersama!","Segi enam bisa disusun tanpa celah dan hemat bahan, bentuk terkuat!","Papan hex itu belah ketupat yang penuh segi enam!","Di hex, sambungan “jembatan” yang punya dua jalan itu kuat!","Ratu lebah hidup jauh lebih lama daripada lebah pekerja!","Lebah bisa melihat sinar ultraviolet! Pola bunga terlihat berbeda bagi kami!","Di musim dingin kami berkumpul dan menggetarkan sayap untuk menghangatkan diri!","Papan hex 11×11 itu yang paling populer!","Bzzz! Akan kusambungkan dengan kecepatan penuh!","Dari bunga ke bunga tanpa istirahat, itulah tugasku!","Soal kerja sama tim, kami tak terkalahkan!"],"marble":["Ada teori bahwa kata Jepang untuk kelereng, “bī-dama”, berasal dari kata Portugis “vidro”, kaca!","Bola di dalam botol ramune juga kelereng kaca, lho~!","Bola untuk bermain juga ditemukan di makam Mesir kuno, lho!","Pola di dalam kaca dibuat dengan memasukkan kaca berwarna yang dipilin!","Kalau diarahkan ke cahaya, pemandangannya terlihat terbalik!","Menyentil kelereng untuk mengenai yang lain, itu keahlianku~!","Ada papan peg solitaire yang memakai kelereng, lho!","Tubuhku yang kenyal pas sekali untuk menggelinding!","Slime bisa jadi apa saja… tapi hari ini aku mau jadi kelereng!","Berkilau! Sepertinya hari ini bakal ada hal baik!","Aku tidak pecah, tapi jangan dilempar, ya~!","Aku menggelinding ke sini untuk main!"],"jelly":["Ubur-ubur itu… tubuhnya hampir semua air… lebih dari 95%…","Ubur-ubur… tidak punya otak… tapi tetap bisa berenang…","Ada juga ubur-ubur… yang bisa jadi muda lagi… “ubur-ubur abadi”…","Ohajiki itu… katanya dulu dimainkan dengan kerikil kecil…","Ohajiki kaca… katanya mulai menyebar di Jepang sejak zaman Meiji…","Ada juga ubur-ubur yang bercahaya… di laut yang gelap… cantik sekali…","Ubur-ubur… katanya sudah ada di laut… lebih dari 500 juta tahun lalu…","Melayang-layang… mengikuti arus… itu juga strategi…","Dengan jari… tik… menyentil ke sebelahnya… bidikan itu penting…","Tubuhku tembus pandang… apa yang kupikirkan… ketahuan tidak, ya…","Ruang ubur-ubur di akuarium… menenangkan, ya…","Hoaam… pelan-pelan saja…"],"redpanda":["Nama “panda” itu awalnya diberikan kepada panda merah, lho!","Kalau kaget, aku berdiri dengan dua kaki dan mengangkat kedua tangan!","Bentuk kendama modern berasal dari “Nichigetsu Ball” yang dirancang di Kure, Hiroshima, tahun 1919!","“Ken” dalam kendama artinya pedang!","Ekorku yang lebat juga bisa jadi syal di hari dingin~!","Panda merah juga makan bambu, lho!","Tahu trik “moshikame”? Bolanya bolak-balik antara cawan besar dan cawan sedang!","Piala Dunia Kendama diadakan di Hatsukaichi, Hiroshima!","Kuncinya, tekuk lutut dengan lentur!","Bunyi “klik” saat berhasil itu bikin ketagihan~!","Aku suka sekali berjemur di atas pohon!","Ayo latihan bersama! Pasti kamu bisa!"],"frog":["Katak juga bernapas lewat kulit, kwak!","Pada berudu, kaki belakang tumbuh lebih dulu, kwak!","Sugoroku sudah dimainkan di Jepang sejak lama sekali, kwak!","“Ban-sugoroku” zaman dulu itu kerabat backgammon, kwak!","Di zaman Edo, orang menikmati suasana perjalanan dengan “sugoroku perjalanan”, kwak!","Yang berbunyi kwak-kwak biasanya katak jantan, kwak!","Katak bisa melompat puluhan kali panjang tubuhnya, kwak!","Dalam bahasa Jepang, “kaeru” berarti katak dan juga “pulang”. Jadi katak jadi jimat perjalanan agar pulang selamat, kwak!","Kalau hujan mau turun, aku jadi bersemangat, kwak!","Dadu, keluarlah angka 6~! Kwak kwak!","Ludo juga sekeluarga dengan sugoroku, kwak!","Ayo lompat-lompat bersama sampai garis akhir, kwak!"],"ghost":["Fukuwarai sudah lama digemari sebagai permainan Tahun Baru di Jepang… hiiuuu~.","Biasanya fukuwarai dimainkan dengan wajah “Okame” atau “Hyottoko”.","Hantu Jepang tidak berkaki… katanya karena pengaruh lukisan zaman Edo…","Bunyi seram “hyuu-dorodoro” berasal dari efek suara teater Jepang.","Cerita hantu di musim panas di Jepang gunanya untuk membuat badan terasa sejuk.","Hehehe, kalau matanya ditutup, niatnya lurus tapi malah melenceng, ya.","Halloween adalah panggung besar hantu setahun sekali!","Kata pepatah Jepang, “keberuntungan datang ke rumah yang penuh tawa”… jadi aku juga datang untuk tertawa.","Kalau tengah malam bidak bergerak sendiri… mungkin itu aku. Hiiuuu~.","Jangan takut. Hantu cuma mencari teman bermain.","Dari tempat yang tak terlihat… aku diam-diam menyemangatimu.","Hiiuuu~… ayo, kita main bersama."],"daruma":["Daruma dibuat meniru Bodhidharma, yang dianggap sebagai pendiri Zen.","Saat membuat permohonan, lukis satu mata. Bila terkabul, lukis mata satunya lagi.","Takasaki di Gunma, Jepang, terkenal sebagai penghasil daruma.","Dalam daruma otoshi, pukul lapisan satu per satu dari samping dengan palu kayu.","Boneka daruma yang selalu bangkit, dasarnya berat, maka ia bangkit berkali-kali.","Warna merah sejak dulu dianggap pengusir roh jahat.","Permainan anak Jepang “Daruma-san ga koronda” juga memakai nama saya.","Tanpa tegang, cepat, dan lurus. Itulah rahasia pukulannya.","Konon tak berkaki dan tak bertangan melambangkan sang guru yang terus bermeditasi.","Jatuh berapa kali pun, bangkit lagi. Itulah jalan saya.","Sudilah ceritakan satu permohonanmu.","Ayo, saya datang!"],"sealion":["Singa laut punya daun telinga, dan bisa berjalan dengan menekuk kaki belakang ke depan!","Anjing laut berbulu juga sekeluarga dengan singa laut, lho!","Ada penelitian tentang singa laut yang mengikuti irama musik!","Kotak di tengah kartu bingo itu kotak gratis!","Bingo Amerika biasanya memakai angka 1 sampai 75!","Untuk memutar bola di ujung hidung, keseimbangan adalah segalanya!","Di dalam air, aku merasakan gerakan ikan dengan kumisku!","Pelaut sejati jago menunggangi ombak, juga momentum pertandingan!","Saat berteriak “Bingo!”, itu momen terbaik, kan!","Tepuk tangan selalu disambut! Auk!","Papan karambol dan meja hoki, semuanya taman bermainku!","Ayo, saatnya pertunjukan!"],"hermit":["Kalau sudah besar, kelomang pindah ke cangkang yang lebih besar.","Kadang kelomang saling bertukar cangkang secara bergiliran.","Kelomang bukan sebangsa kepiting sejati, lho.","Kalau menemukan kotak yang pas, hati terasa tenang.","Kalau tak ada cangkang, kelomang kadang masuk ke kaleng bekas.","Di teka-teki geser, kuncinya adalah cara memakai petak kosong.","Capit kiri dan kanan kelomang sering berbeda ukuran.","Kotak yang sempit justru membantu pikiran jadi teratur.","Pantai di malam hari adalah jalan-jalan para kelomang.","Tema penelitian hari ini… “ukuran kotak yang optimal”.","Untuk teka-teki meloloskan diri, amati dulu keseluruhannya.","Nah, mari kita mulai penelitiannya."]},"trivia":{"chess":["Kejuaraan dunia catur resmi dimulai tahun 1886, dan juara pertamanya adalah Steinitz.","Bentuk bidak “Staunton” yang dipakai di turnamen sekarang dirancang tahun 1849.","Langkah awal pion maju dua petak adalah aturan tambahan agar permainan berjalan lebih cepat.","Kalau selama 50 langkah tak ada tangkapan atau gerakan pion, permainan bisa dinyatakan seri.","Hanya dengan dua langkah pertama masing-masing, sudah ada sekitar 200.000 kemungkinan jalannya permainan.","“Pat” adalah keadaan saat giliranmu tapi tak ada langkah sah dan rajamu tidak diskak. Hasilnya seri."],"shogi":["Menaruh dua pion di lajur yang sama, “nifu”, adalah pelanggaran.","Skakmat dengan menjatuhkan pion dari tangan, “uchifuzume”, juga pelanggaran.","Di zaman Edo, gelar Meijin diwariskan di dalam keluarga-keluarga ahli shogi.","Dulu ada juga varian yang bidaknya jauh lebih banyak, seperti “dai shogi”.","Kalau posisi yang sama muncul empat kali, itu “sennichite” dan permainan diulang.","Saat dipromosikan, bidak dibalik, biasanya ke sisi bertulisan merah."],"go":["Go diperkirakan sudah sampai di Jepang sebelum zaman Nara.","Di gudang harta Shōsōin di Nara, Jepang, masih tersimpan papan go yang indah.","Tahun 2016, AI “AlphaGo” mengalahkan pemain top Lee Sedol.","Batu go yang sudah ditaruh tidak pernah dipindahkan.","Papan 9×9 dan 13×13 sangat cocok untuk latihan pemula.","Dalam “ko”, kamu harus menunggu satu langkah sebelum mengambil kembali, supaya bentuk yang sama tak berulang terus."],"reversi":["Kejuaraan Dunia Othello diadakan sejak tahun 1977.","Pada papan kecil 6×6, Othello sudah diketahui dimenangkan pemain kedua.","Tahun 2023, Othello 8×8 dipecahkan komputer: jika keduanya bermain sempurna, hasilnya seri.","Kamu hanya boleh pas kalau tak ada tempat untuk melangkah. Kalau bisa melangkah, tidak boleh pas.","Petak C dan petak X di sebelah sudut berbahaya, karena sudutnya jadi mudah direbut.","Permainan dimulai dengan empat keping yang ditaruh menyilang di tengah papan."],"gomoku":["Gomoku tanpa batasan di papan 15×15 terbukti dimenangkan pemain pertama.","Kejuaraan Dunia Renju diadakan sejak tahun 1989.","Federasi Renju Internasional didirikan tahun 1988.","Dalam bahasa Inggris pun, permainan ini tetap disebut “Gomoku”.","Di luar Jepang ada aturan seperti “Pro” yang membatasi langkah pembuka pemain pertama.","Kalau berhasil membuat “empat-tiga” yang tak bisa dihentikan, kemenangan hampir pasti."],"checkers":["Di dam Amerika, bidak berwarna gelap jalan lebih dulu.","Tahun 1990-an, program “Chinook” bertanding melawan juara dunia manusia.","Dam internasional di papan 10×10 memakai 20 bidak per pemain.","Raja di dam internasional adalah “raja terbang” yang bisa melaju sejauh apa pun secara diagonal.","Di banyak aturan, kalau ada bidak yang bisa ditangkap, wajib ditangkap.","Meski papannya 8×8 seperti catur, yang dipakai hanya petak gelap."],"xiangqi":["Meriam menangkap dengan melompati tepat satu bidak.","Kedua jenderal tidak boleh berhadapan di lajur yang sama tanpa ada bidak di antaranya.","Di xiangqi, Merah jalan lebih dulu.","Setelah menyeberangi sungai, prajurit juga bisa bergerak ke samping.","Bidaknya bundar dan pipih, dibedakan dari huruf yang tertulis di atasnya.","Di Vietnam, permainan ini digemari dengan nama “cờ tướng”."],"janggi":["Di janggi, raja bisa bergerak di sepanjang garis diagonal selama di dalam istana.","Meriam harus melompati satu bidak untuk bergerak, juga untuk menangkap.","Prajurit bisa maju dan ke samping, tapi tidak bisa mundur.","Kalau tidak ada yang kena skakmat, pemenang bisa ditentukan dengan poin bidak.","Bidaknya segi delapan, dan warna hurufnya menunjukkan pihak.","“Janggun!” adalah seruan saat memberi skak."],"tafl":["“Tafl” berarti “papan” dalam bahasa Nordik kuno.","“Hnefatafl” yang terkenal sering diterjemahkan sebagai “papan raja”.","Pihak penyerang punya bidak sekitar dua kali lipat pihak bertahan.","Bidak ditangkap dengan mengapitnya di antara dua bidakmu.","Di banyak aturan, penyerang menang jika mengepung raja dari empat arah.","Bidak permainan pernah ditemukan di makam bangsa Viking."],"ur":["Papan permainan Ur dipamerkan di British Museum, London.","Kalau berhenti di petak bermotif bunga (roset), kamu boleh melempar lagi.","Irving Finkel dari British Museum memecahkan cara bermainnya dari lempeng tanah liat.","Di balik kotak permainan dari makam Tutankhamun juga ada papan 20 petak.","Permainan Ur juga disebut “Permainan Dua Puluh Petak”.","Di Kochi, India, permainan yang sangat mirip masih dimainkan sampai abad ke-20."],"senet":["Papan senet punya 30 petak: tiga baris kali sepuluh.","“Senet” diperkirakan berarti “melewati”.","Belakangan, permainan ini dianggap melambangkan perjalanan ke alam baka.","Aturan aslinya tidak tersisa; aturan sekarang adalah rekonstruksi para peneliti.","Empat tongkat lempar dilempar, dan jumlah sisi putih menentukan jumlah langkah.","Ada juga papan senet berbentuk kotak dengan laci."],"morris":["“Men” dalam “Nine Men's Morris” artinya bidak.","Ada juga versi papan kecil: “Three Men's Morris” dan “Six Men's Morris”.","Tahun 1990-an, analisis komputer menunjukkan permainan sempurna berakhir seri.","Kalau bidakmu tinggal dua, kamu kalah.","Kalau tak ada tempat untuk bergerak, kamu juga kalah.","Di Inggris zaman dulu, papan besar kadang diukir di lapangan rumput desa."],"connect4":["Connect Four dirilis oleh perusahaan Amerika Milton Bradley.","Tahun 1988, James Allen dan Victor Allis memecahkan permainan ini secara terpisah.","Kalau pemain pertama mulai di luar kolom tengah, balasan yang tepat membuatnya tak bisa menang.","Kepingnya jatuh ke bawah, jadi bisa disebut “empat sejajar dengan gravitasi”.","Ada banyak variasi aturan dengan ukuran papan yang berbeda.","Mendatar, tegak, atau diagonal, empat sejajar ke arah mana pun menang."],"dots":["Matematikawan Berlekamp menulis satu buku khusus tentang permainan ini.","“Aturan rantai panjang” menentukan bentuk yang diincar pemain pertama dan kedua.","Pertarungan babak tengah adalah adu sabar: siapa yang terpaksa menggambar garis ketiga.","Sengaja memberikan dua kotak juga salah satu teknik penting.","Permainan ini dimainkan di pojok buku tulis di sekolah-sekolah seluruh dunia.","Papan kecil 3×3 kotak pun ternyata cukup dalam."],"mancala":["Di Afrika Timur dimainkan mancala empat baris bernama “bao”.","“Kalah”, yang populer di Amerika, adalah aturan yang dibuat tahun 1940-an.","Kadang biji diganti dengan kacang, kerang, atau kerikil.","Kalah dengan enam lubang dan empat biji per lubang sudah diketahui dimenangkan pemain pertama jika bermain tepat.","Di “oware”, kalau biji lawan hampir habis, kamu wajib memberinya biji.","Keluarga mancala secara garis besar terbagi dua: yang berlubang dua baris dan empat baris."],"backgammon":["Segitiga di papan disebut “poin”, jumlahnya 24.","Yang pertama mengeluarkan ke-15 bidaknya menang.","Menang sebelum lawan mengeluarkan satu bidak pun disebut “gammon”: poin dua kali lipat.","Kalau bidak lawan masih ada di daerahmu atau di bar, itu “backgammon”: tiga kali lipat!","Di Timur Tengah disebut “tawla”, di Rusia dan sekitarnya “nardy”.","“Ban-sugoroku” Jepang juga kerabat backgammon, sudah masuk ke Jepang di zaman Nara."],"hex":["Piet Hein adalah penyair sekaligus matematikawan dari Denmark.","Awalnya diperkenalkan di koran Denmark dengan nama “Polygon”.","Di universitas Amerika, permainan ini juga disebut “Nash”.","Karena pemain pertama terlalu diuntungkan, ada aturan “swap” yang membolehkan pemain kedua menukar batu pertama.","Di papan kecil, strategi pasti menang sudah ditemukan komputer.","Papannya belah ketupat; tujuannya menyambungkan dua sisi yang berhadapan."],"fanorona":["Papannya berupa titik 9×5 yang dihubungkan garis.","Masing-masing punya 22 bidak; hanya titik tengah yang kosong di awal.","Tahun 2000-an, analisis komputer menunjukkan permainan sempurna berakhir seri.","Saat menangkap beruntun, kamu tidak boleh bergerak ke arah yang sama dua kali berturut-turut.","Saat menangkap beruntun, kamu juga tidak boleh kembali ke titik yang sudah dilewati.","Babak awal adalah pertempuran sengit saling tangkap; babak akhir adalah adu siasat dengan sedikit bidak."],"ugolki":["Papannya 8×8, sama seperti papan catur.","Jumlah bidaknya ada aturan 9 (3×3), 12 (3×4), dan lainnya.","Saat melompat, kamu boleh melompati bidakmu sendiri maupun bidak lawan.","Melompat beruntun untuk melesat jauh sekaligus itu rasanya asyik.","Lewat Halma, ugolki bersaudara dengan dam Cina.","Ada juga aturan yang melarang berdiam di daerah tujuan lawan untuk menghalanginya."],"agon":["Papan agon terdiri dari 91 petak segi enam.","Masing-masing pemain bermain dengan satu ratu dan enam pengawal.","Bidak hanya bisa bergerak mendekati pusat atau mengitari cincin yang sama.","Kalau bidak lawan diapit dua bidakmu, kamu bisa mengusirnya ke luar.","Sekitar tahun 1842, permainan ini sudah dijual di Inggris.","Cincin-cincin papan diberi warna berbeda; makin ke dalam, makin dekat dengan kemenangan."],"konane":["Selain 8×8, kōnane juga dimainkan di papan yang jauh lebih besar.","Awalnya papan diisi penuh hitam-putih berselang-seling, lalu dua bidak di tengah diambil.","Saat melompat beruntun, kamu hanya boleh melompat lurus ke arah yang sama.","Konon raja-raja Hawaii juga menikmati permainan ini.","Permainan ini tidak pernah berakhir seri.","Kōnane sering dibahas dalam penelitian matematika “teori permainan kombinatorial”."],"amazons":["Amazon bergerak sama seperti ratu di catur.","Papannya 10×10, dan masing-masing memakai empat amazon.","Petak yang ditutup panah tidak bisa dipakai sampai permainan berakhir.","Di akhir permainan, pertarungannya adalah menghitung luas wilayahmu sendiri.","Permainan ini tidak pernah berakhir seri.","Untuk langkah pertama saja, ada lebih dari 2.000 cara bermain."],"ludo":["Pachisi India dimainkan di papan kain, dengan kulit kerang sebagai pengganti dadu.","Papan berbentuk salib diwarisi dari pachisi.","“Parcheesi” dari Amerika dan “Mensch ärgere Dich nicht” dari Jerman juga kerabatnya.","Di banyak aturan, berhenti di petak yang sama dengan bidak lawan akan mengirimnya kembali ke awal.","Bisa dimainkan berempat, jadi seluruh keluarga bisa ikut.","Di India, ludo di ponsel pintar sempat sangat populer."],"carrom":["Papan karambol berbentuk persegi dengan kantong di keempat sudutnya.","Sembilan putih, sembilan hitam, dan satu ratu merah: totalnya 19 bidak.","Federasi Karambol Internasional didirikan tahun 1988.","Striker diletakkan di garis di depanmu sebelum disentil.","Kejuaraan dunia juga diadakan, dan pemain dari India serta Sri Lanka sangat kuat.","Ada yang bilang rasanya seperti main biliar dengan jari."],"crokinole":["Papannya bundar, dengan zona 5, 10, dan 15 poin makin ke tengah.","Di sekeliling zona 15 poin berdiri delapan pasak kecil.","Kejuaraan dunianya diadakan setiap tahun di Ontario, Kanada.","Papannya biasanya dari kayu, dan banyak papan buatan tangan yang indah.","Bisa dimainkan satu lawan satu atau dalam tim berdua.","Keping disentil dengan ujung jari supaya meluncur."],"hockey":["Air hockey lahir di Amerika Serikat pada awal tahun 1970-an.","Kepingnya meluncur di atas udara, jadi hampir tak ada gesekan.","Di turnamen, kecepatan keping bisa lebih dari 100 km/jam.","Alat pemukulnya juga disebut “mallet”.","Tembakan yang dipantulkan ke dinding untuk membuat sudut disebut “bank shot”.","Banyak aturan memakai sistem siapa duluan mencetak 7 gol yang menang."],"alquerque":["Papannya berupa titik 5×5 yang dihubungkan garis, termasuk garis diagonal.","Masing-masing punya 12 bidak; hanya titik tengah yang kosong di awal.","Papan alquerque kadang ditemukan terukir di batu bangunan tua Eropa.","Di banyak aturan, kalau bisa menangkap dengan melompat, kamu wajib melakukannya.","Fanorona juga diperkirakan berasal dari alquerque.","Nama “alquerque” konon berasal dari kata Arab “el-qirkat”."],"poker":["Kombinasi terkuat di poker adalah royal flush.","Peluang mendapat royal flush dari lima kartu yang dibagikan sekitar 1 banding 650.000.","Di Texas hold'em, kamu menyusun kombinasi dari dua kartu di tangan dan lima kartu bersama.","Konon poker menyebar di kapal-kapal Sungai Mississippi di Amerika abad ke-19.","Turnamen dunia “World Series of Poker” dimulai tahun 1970.","Tahun 2019, AI “Pluribus” mengalahkan pemain profesional di poker enam pemain."],"blackjack":["As dan kartu bernilai 10 yang jumlahnya 21 disebut “blackjack”.","Kartu bergambar J, Q, dan K semuanya dihitung 10.","As bisa bernilai 1 atau 11, kartu yang praktis.","Tahun 1962, matematikawan Edward Thorp menerbitkan buku cara menang yang menghebohkan.","Di banyak aturan, bandar terus mengambil kartu sampai mencapai 17 atau lebih.","Konon permainan ini berasal dari permainan Prancis “vingt-et-un” (dua puluh satu)."],"baccarat":["Baccarat adalah permainan di mana jumlah yang paling dekat ke 9 menang.","Kartu 10 dan kartu bergambar dihitung 0.","Kalau jumlahnya dua digit, hanya angka satuannya yang dipakai.","Kamu menebak siapa yang menang: “Banker”, “Player”, atau “Tie” (seri).","Kalau dua kartu pertama berjumlah 8 atau 9, itu “natural” dan hasilnya langsung ditentukan.","Mengambil kartu ketiga atau tidak, ditentukan oleh tabel yang sudah pasti."],"solitaire":["Kata “solitaire” berasal dari kata yang berarti “sendirian”.","Di Inggris permainan ini disebut “patience” (kesabaran).","Tahun 1990, Klondike disertakan di komputer pribadi dan menyebar ke seluruh dunia.","Dari 32.000 pembagian FreeCell yang terkenal, katanya hanya satu yang tak bisa diselesaikan.","Nama Klondike berasal dari nama daerah demam emas di Kanada.","Di Spider, tujuannya menyusun delapan set K sampai A dengan jenis yang sama. Kaki laba-laba juga delapan!"],"peg":["Peg solitaire konon sedang tren di Prancis abad ke-17.","Sebuah cetakan grafis dari tahun 1697 menggambarkan seorang bangsawan wanita memainkannya.","Papan Inggris berbentuk salib punya 33 lubang.","Menyisakan pasak terakhir di lubang tengah adalah penyelesaian yang paling indah.","Pasak yang dilompati diambil dari papan.","Papan gaya Prancis punya 37 lubang."],"sudoku":["Sudoku menjadi tren dunia sekitar tahun 2005, dipicu oleh koran-koran Inggris.","Pendahulunya, “Number Place”, dimuat di majalah teka-teki Amerika tahun 1979.","Penciptanya konon adalah arsitek Howard Garns.","“Sudoku” adalah singkatan dari frasa Jepang yang artinya “angkanya harus tunggal”.","Sudoku tidak butuh hitungan! Angka hanya dipakai sebagai simbol.","Kejuaraan Dunia Sudoku diadakan sejak tahun 2006."],"speedsudoku":["Susunan jawaban sudoku 4×4 totalnya hanya ada 288 macam.","Kalau 4×4, tiap baris cukup diisi 1 sampai 4 masing-masing sekali. Adu cepat!","Sudoku kecil sangat cocok sebagai pengantar latihan sudoku.","Begitu melihat angka, langsung periksa baris, kolom, dan bloknya!","Kunci menyelesaikan dengan cepat: temukan baris yang sudah berisi tiga angka.","Cepat dan tepat, kalau dua-duanya ada, rekor pun pecah!"],"samegame":["SameGame berasal dari “Chain Shot!”, permainan buatan Jepang tahun 1985.","Dua blok atau lebih berwarna sama yang tersambung bisa dihapus.","Di banyak aturan, semakin besar kelompok yang dihapus sekaligus, semakin besar poinnya.","Kalau semua blok berhasil dihapus, biasanya dapat bonus.","Setelah dihapus, blok di atas jatuh, dan kolom kosong bergeser ke kiri.","Memikirkan warna mana yang tersisa terakhir adalah teknik pemain mahir."],"shanghai":["Shanghai terkenal sebagai permainan komputer yang dirilis Activision di Amerika tahun 1986.","Penciptanya adalah Brodie Lockard.","Susunan klasiknya adalah bentuk “Kura-kura” dari 144 ubin mahjong yang ditumpuk.","Ambil ubin yang sama dua per dua; kalau semuanya terambil, kamu menang!","Ubin yang bisa diambil hanya yang tidak tertimpa dan sisi kiri atau kanannya terbuka.","Ubin musim dan ubin bunga bisa dipasangkan dengan sesama kelompoknya."],"jailbreak":["Teka-teki geser klasik, “teka-teki 15”, sangat populer di Amerika sekitar tahun 1880.","Ada susunan teka-teki 15 yang sama sekali tidak bisa diselesaikan.","“Hakoiri Musume” dari Jepang adalah teka-teki geser untuk memindahkan sang putri ke pintu keluar.","Penyelesaian terpendek Hakoiri Musume konon 81 langkah.","“Rush Hour”, menggeser mobil menuju pintu keluar, juga keluarga teka-teki geser.","Kuncinya, siapkan dulu jalan untuk blok besar."]},"day":{"01-01":["Selamat Tahun Baru! Tahun ini juga ayo main banyak-banyak!","Tahun Baru! Sudah main partai pertamamu tahun ini? Di Jepang, kegiatan pertama di tahun baru itu istimewa!"],"01-02":["Permainan Tahun Baru di Jepang: sugoroku, fukuwarai, dan karuta! Kamu suka yang mana?"],"01-03":["Di Jepang, tiga hari libur Tahun Baru berakhir hari ini. Hati-hati jangan kebanyakan makan kue mochi!"],"01-05":["Di Jepang, 5 Januari adalah “Hari Go”! Angka 1 dan 5 bisa dibaca “i-go” dalam bahasa Jepang."],"01-07":["Di Jepang, hari ini orang makan bubur tujuh tanaman musim semi. Bisa sebutkan semuanya?"],"01-11":["Di Jepang, hari ini Kagami-biraki! Kue mochi Tahun Baru yang sudah keras enak dimakan dalam sup kacang merah manis."],"01-2Mo":["Di Jepang, hari ini Hari Kedewasaan. Selamat untuk semua yang sudah menjadi dewasa!"],"02-03":["Sekarang musim Setsubun di Jepang! “Setan keluar, untung masuk!” Katanya kacang dimakan sebanyak umurmu."],"02-11":["Hari ini Hari Peringatan Berdirinya Negara. Di Jepang, ini hari libur nasional."],"02-14":["Hari ini Hari Valentine! Kamu suka cokelat?"],"02-15":["15 Februari adalah “Hari Kuda Nil Sedunia”! Mau dengar cerita tentang kuda nil?"],"02-22":["Di Jepang, 2/22 dibaca mirip “nyan nyan nyan” (meong meong meong), jadi ini Hari Kucing! Meong~!"],"02-29":["Hari ini hari kabisat, cuma ada empat tahun sekali! Rasanya seperti dapat bonus, ya!"],"03-03":["Di Jepang, hari ini Hinamatsuri, festival boneka! Katanya tiga warna kue hishi-mochi masing-masing punya arti.","3 Maret juga “Hari Satwa Liar Sedunia”, lho."],"03-14":["Di Jepang, hari ini White Day! Selain itu, 3.14 juga “Hari Pi”, lho.","14 Maret adalah hari ulang tahun fisikawan Einstein."],"03-16":["16 Maret adalah “Hari Panda” di Amerika!"],"03-20":["Sekitar saat ini adalah ekuinoks musim semi. Panjang siang dan malam hampir sama.","20 Maret juga “Hari Katak Sedunia”! Kwak!"],"03-22":["22 Maret adalah “Hari Anjing Laut Internasional”!"],"04-01":["Hari ini April Mop! …Kalau kubilang sebenarnya aku AI terkuat, kamu percaya?"],"04-04":["4 April adalah hari ulang tahun matematikawan Édouard Lucas, yang memopulerkan Dots and Boxes dan Menara Hanoi."],"04-07":["7 April adalah “Hari Berang-berang Internasional”!"],"04-17":["17 April adalah hari ulang tahun Leonard Woolley, arkeolog yang menggali makam kerajaan Ur."],"04-22":["Hari ini Hari Bumi. Hari untuk memikirkan planet kita."],"04-23":["23 April adalah “Hari Buku Sedunia”, juga hari wafatnya Shakespeare. Dialah asal nama Othello!"],"04-25":["25 April adalah “Hari Penguin Sedunia”!"],"04-29":["Di Jepang, hari ini Hari Shōwa. Awal Golden Week, libur panjang Jepang!"],"04-30":["30 April adalah hari ulang tahun Claude Shannon, bapak teori informasi. Ia juga menulis makalah tentang komputer catur."],"05-03":["Di Jepang, hari ini Hari Konstitusi. Tepat di tengah Golden Week!"],"05-04":["Di Jepang, hari ini Hari Hijau. Ayo istirahat sejenak sambil memandangi pohon dan bunga."],"05-05":["Di Jepang, hari ini Hari Anak! Sudah lihat bendera ikan koi (koinobori)?"],"05-11":["Pada hari ini tahun 1997, komputer “Deep Blue” mengalahkan juara dunia catur."],"05-14":["Di Jepang, 14 Mei adalah “Hari Kendama”! “Nichigetsu Ball”, cikal bakal kendama modern, didaftarkan pada hari ini tahun 1919."],"05-20":["20 Mei adalah “Hari Lebah Sedunia”! Bzzz bzzz!"],"05-23":["23 Mei adalah “Hari Kura-kura Sedunia”! Juga hari ulang tahun naturalis Linnaeus, yang mencatat permainan tafl."],"05-2Su":["Hari ini Hari Ibu. Ayo ucapkan terima kasih!"],"06-10":["Di Jepang, hari ini “Hari Peringatan Waktu”. Hari untuk menghargai waktu."],"06-13":["13 Juni adalah hari ulang tahun matematikawan John Nash, salah satu pencipta Hex."],"06-21":["Sekitar saat ini adalah titik balik matahari Juni. Di belahan bumi utara, siangnya paling panjang dalam setahun."],"06-23":["23 Juni adalah hari ulang tahun Alan Turing, bapak komputer. Ia juga merancang program bermain catur."],"06-3Su":["Hari ini Hari Ayah. Coba ucapkan terima kasih untuk semuanya!"],"07-07":["Di Jepang, hari ini Tanabata! Permohonan apa yang mau kamu tulis di kertas tanzaku? “Semoga menang main”?"],"07-13":["13 Juli adalah hari ulang tahun Ernő Rubik, pencipta Kubus Rubik."],"07-20":["20 Juli adalah “Hari Catur Internasional”! Federasi Catur Internasional (FIDE) didirikan pada hari ini tahun 1924.","Pada hari ini tahun 1969, Apollo 11 mendarat di Bulan."],"07-3Mo":["Di Jepang, hari ini Hari Laut. Makhluk laut pasti ikut senang!"],"08-08":["8 Agustus adalah “Hari Kucing Sedunia”! Meong!"],"08-11":["Di Jepang, hari ini Hari Gunung. Pemandangan dari puncak gunung itu luar biasa, ya."],"08-12":["12 Agustus adalah “Hari Gajah Sedunia”! Ngoooo!"],"08-13":["Sekitar saat ini adalah Obon. Di Jepang, ada tradisi menyambut kembali arwah leluhur."],"08-31":["Agustus sudah berakhir. Sudah punya kenangan musim panas?"],"09-01":["Di Jepang, 1 September adalah Hari Pencegahan Bencana. Sudah siap untuk keadaan darurat?"],"09-09":["Di Jepang, hari ini Festival Krisan (Chōyō). Dua angka 9 berjajar, hari yang cocok untuk sudoku 9×9!"],"09-23":["Sekitar saat ini adalah ekuinoks musim gugur. Di belahan bumi utara, malam akan makin panjang."],"09-3Mo":["Di Jepang, hari ini Hari Penghormatan Lansia. Main bersama kakek dan nenek juga asyik!"],"10-04":["4 Oktober adalah “Hari Hewan Sedunia”! Semua Atlamo ikut merayakan!"],"10-27":["27 Oktober adalah “Hari Boneka Teddy”! Ini hari ulang tahun Presiden Roosevelt."],"10-2Mo":["Di Jepang, hari ini Hari Olahraga. Setelah menggerakkan badan, bagaimana kalau senam otak?"],"10-31":["Hari ini Halloween! Trick or treat! Kalau tidak beri permen, aku jahili, ya!"],"11-03":["Di Jepang, hari ini Hari Kebudayaan, hari libur nasional."],"11-04":["Pada hari ini tahun 1922, pintu masuk makam Tutankhamun ditemukan. Di dalamnya ada papan senet juga!"],"11-11":["Di Jepang, 11 November adalah “Hari Origami”! Angka 1 yang berjajar terlihat rapi sekali."],"11-15":["Di Jepang, hari ini Shichi-Go-San, hari merayakan pertumbuhan anak-anak."],"11-17":["Di Jepang, 17 November adalah “Hari Shogi”! Di zaman Edo, “shogi istana” di hadapan shogun diadakan pada hari ini."],"11-23":["Di Jepang, hari ini Hari Terima Kasih Buruh. Ucapkan terima kasih juga untuk dirimu yang selalu bekerja keras!","23 November adalah hari ulang tahun Alfonso X dari Spanyol, yang memerintahkan pembuatan “Kitab Permainan”."],"12-16":["16 Desember adalah hari ulang tahun Piet Hein, pencipta Hex."],"12-22":["Sekitar saat ini adalah titik balik matahari Desember. Di Jepang, orang berendam air jeruk yuzu dan makan labu."],"12-24":["Hari ini Malam Natal! Kamu ingin hadiah apa?"],"12-25":["Selamat Natal! Hari ini ayo main santai, ya!"],"12-31":["Hari ini malam Tahun Baru! Terima kasih sudah banyak main bersamaku tahun ini!","Hari terakhir dalam setahun. Tahun depan juga ayo main banyak-banyak bersama!"]},"dsp":{"01-05":{"stone":["Hari ini Hari Go. …Bagi penguin sepertiku pun, ini hari istimewa."],"goke":["Hari Go, Bos! Ayo kita adakan obral besar batu go!"]},"02-15":{"hippo":["Hari ini Hari Kuda Nil Sedunia… hariku… untuk merayakannya… ayo tidur siang…"]},"02-22":{"joker":["Hari ini Hari Kucing di Jepang, meong! Bintangnya aku, meong! Meong-haha!"]},"03-14":{"tile":["Hari ini Hari Pi. 3,14159265… bip bip bip, angkanya berlanjut tanpa akhir."]},"03-16":{"flippanda":["Hari ini Hari Panda… katanya… ayo bersulang dengan bambu…"]},"03-20":{"frog":["Hari ini Hari Katak Sedunia, kwak! Ayo semua rayakan bersama, kwak kwak!"]},"03-22":{"seal":["Hari ini Hari Anjing Laut Internasional! Aku rayakan dengan guling-guling~!"]},"04-01":{"joker":["April Mop, meong! Hari ini semua yang kukatakan… mungkin benar, meong?"],"ghost":["April Mop… sebenarnya aku bukan hantu… bercanda, hiiuuu~."]},"04-07":{"beaver":["Hari ini Hari Berang-berang Internasional! Semangat membangun bendunganku membara!"]},"04-25":{"stone":["Hari ini Hari Penguin Sedunia. …Aku sedikit senang."]},"05-05":{"daruma":["Hari ini Hari Anak di Jepang! Saya pun berdoa agar anak-anak tumbuh sehat dan kuat."]},"05-14":{"redpanda":["Hari ini Hari Kendama! Hariku~! Lihat, aku tancapkan bolanya ke ujung pedang!"]},"05-20":{"bee":["Hari ini Hari Lebah Sedunia! Bzzz bzzz, bintangnya aku!"]},"05-23":{"disc":["Hari ini Hari Kura-kura Sedunia… hariku… ayo rayakan pelan-pelan…"]},"06-10":{"camel":["Hari ini Hari Peringatan Waktu di Jepang. Jam pasirku pun hari ini tampak sangat bangga."]},"07-07":{"crane":["Hari ini Tanabata di Jepang. Mari tulis permohonan di kertas tanzaku dan ikatkan pada bambu."]},"07-13":{"hippo":["Hari ini ulang tahun Pak Rubik… ayo rayakan dengan menyelesaikan kubus… hoaam."]},"07-20":{"knight":["Hari ini Hari Catur Internasional! Bagi seorang ksatria, tak ada hari yang lebih membanggakan!"],"pawn":["Hari ini Hari Catur! Pion juga ikut merayakan, mbeek~!"],"rook":["Hari Catur… benteng juga pesta di menaranya…"],"bishop":["Hari ini Hari Catur. Semoga semua bidak di papan diberkati."]},"08-08":{"joker":["Hari Kucing Sedunia, meong! Kamu boleh mengelusku, meong."]},"08-12":{"rook":["Hari ini Hari Gajah Sedunia, katanya… aku kan gajah… hehe…"]},"10-27":{"teddy":["Hari ini Hari Boneka Teddy! Seperti hari ulang tahunku! Peluk aku, dong!"]},"10-31":{"ghost":["Halloween! Hari ini saja hantu boleh berjalan terang-terangan! Hiiuuu~!"],"joker":["Halloween, meong! Kalau tidak kasih permen, aku jahili, meong!"]},"11-11":{"crane":["Hari ini Hari Origami di Jepang. Maukah kita melipat seekor burung jenjang?"]},"11-17":{"shogi":["Hari ini Hari Shogi di Jepang! Saya sudah duduk bersimpuh menunggu sejak pagi!"],"ryuou":["Hari ini Hari Shogi! Hari ini hormatilah aku, sang Raja Naga, secara istimewa!"],"keima":["Hari Shogi! Aku juga lompat tinggi untuk merayakannya! Cit!"]},"12-16":{"bee":["Hari ini ulang tahun Piet Hein, pencipta Hex! Terima kasih untuk segi enamnya!"]}},"mon":{"1":["Januari cocok sekali untuk memulai hal baru! Sudah menentukan target tahun ini?","Di hari yang dingin, main di ruangan hangat itu paling enak."],"2":["Februari bulan paling pendek dalam setahun. Cepat sekali berlalunya.","Kalau dingin, hangatkan tangan dulu sebelum main!"],"3":["Di Jepang, Maret adalah musim perpisahan dan pertemuan baru.","Di Jepang cuaca mulai menghangat. Musim semi sudah dekat!"],"4":["Sudah April! Musim yang bagus untuk memulai hal baru!","Di Jepang, ini musim bunga sakura! Satu partai sambil menikmati bunga juga asyik."],"5":["Mei musim yang segar. Main dengan jendela terbuka rasanya nyaman.","Di Jepang, ini musim daun-daun hijau muda yang indah."],"6":["Di Jepang, Juni adalah musim hujan. Cocok untuk main di rumah.","Di Jepang, ini musim bunga hortensia yang cantik."],"7":["Juli! Di Jepang musim panas sudah tiba. Siapkan minuman dingin, lalu ayo main!","Kalau panas, jangan memaksakan diri. Main di ruangan yang sejuk, ya."],"8":["Banyak orang libur di bulan Agustus. Bisa main sepuasnya!","Malam musim panas di Jepang, kembang api dan suara serangga juga menyenangkan."],"9":["Di Jepang, September masih ada hari yang panas, tapi malamnya mulai sejuk.","Di Jepang, ini musim menikmati bulan. Malam bulan purnama terasa istimewa."],"10":["Oktober puncak musim gugur di Jepang. Musim membaca, musim main game!","Di Jepang, ini musim daun-daun merah mulai indah."],"11":["Di Jepang, November adalah musim daun berubah warna. Cuacanya pas untuk main game.","Hari-hari makin pendek. Partai malam jadi makin seru."],"12":["Desember! Penutup tahun. Pertandingan terbaikmu tahun ini yang mana?","Di Jepang mulai dingin. Jaga diri supaya tidak masuk angin, ya."]},"wd":[["Hari Minggu! Hari untuk main santai!","Minggu malam, main secukupnya saja untuk persiapan besok."],["Hari Senin. Minggu ini juga ayo berusaha bersama!","Senin itu agak berat, ya. Senang kamu mampir untuk istirahat."],["Hari Selasa. Bagaimana minggumu sejauh ini?"],["Hari Rabu! Sudah setengah minggu."],["Hari Kamis. Akhir pekan sebentar lagi!"],["Hari Jumat! Terima kasih atas kerja kerasmu minggu ini!","Jumat malam, mau main sedikit lebih lama?"],["Hari Sabtu! Hari yang pas untuk mencoba permainan baru.","Sabtu! Ayo main sepuasnya!"]],"g":{"morning":["Selamat pagi! Hari ini mau main apa?","Udara pagi itu segar, ya. Kepala jadi jernih!","Pagi~! Hari ini juga mohon kerja samanya, ya!","Selamat pagi! Sebaiknya cek misi harian selagi pagi."],"day":["Halo! Tadi makan siang apa?","Hai, {name}! Istirahat sebentar di sini, yuk.","Halo! Kamu datang di saat yang tepat!","Bagaimana kalau satu partai di jam istirahat siang?"],"evening":["Selamat malam! Satu partai setelah makan malam juga asyik.","Terima kasih atas kerja kerasmu hari ini! Bersantailah.","Selamat malam, {name}! Hari ini ada kejadian baik?","Langit sore tadi cantik, ya."],"night":["Selamat malam, si burung hantu. Main sambil mengistirahatkan mata, ya.","Malam yang tenang. Pas untuk berpikir dalam-dalam.","Masih bangun jam segini… kamu pasti suka bertanding, ya?","“Satu partai lagi saja…” sering bilang begitu, kan? Hihi."],"call":["Ya! Memanggilku?","Wah, kaget! Ada apa?","{name}! Kamu datang menemuiku, ya!","Mau ngobrol? Atau main bersama?"],"trivia":["Dengar, deh!","Kamu tahu ini?","Aku kasih tahu hal yang bikin “wah”!"],"bye":["Hari ini seru, ya!","Kutunggu pertandingan serunya!","Semangat! Aku menyemangatimu dari sini!","Kalau capek, jangan lupa istirahat, ya.","Sampai jumpa! Ayo ngobrol kapan saja!","Sehat-sehat sampai kita bertemu lagi!"]}}, 't3');
